if (element.querySelector('#persistent-filter-sidebar')) return;

var sidebar = document.createElement('div');
sidebar.id = 'persistent-filter-sidebar';
sidebar.setAttribute('class', 'style-scope ytd-two-column-search-results-renderer');
sidebar.style.cssText = 'width:260px;min-width:260px;background:#f9f9f9;border-left:1px solid #e0e0e0;padding:16px;position:sticky;top:0;height:100vh;overflow-y:auto;font-family:Roboto,Arial,sans-serif;';

var html = '';

// Feature sort section
html += '<div style="margin-bottom:20px;">';
html += '<h3 style="margin:0 0 12px 0;font-size:14px;font-weight:500;color:#030303;display:flex;align-items:center;gap:6px;">⚙️ Filter Results</h3>';
html += '</div>';

// Type filter
html += '<div style="margin-bottom:18px;">';
html += '<div style="font-size:13px;font-weight:500;color:#606060;margin-bottom:8px;text-transform:uppercase;letter-spacing:0.5px;">Type</div>';
html += '<div style="display:flex;flex-wrap:wrap;gap:6px;">';
var types = ['Video', 'Playlist', 'Channel', 'Movie', 'Live'];
types.forEach(function(t) { html += '<span class="filter-chip" data-filter="type" data-value="' + t + '" style="display:inline-block;padding:6px 14px;border-radius:16px;font-size:13px;cursor:pointer;background:#f2f2f2;color:#030303;border:1px solid #e5e5e5;transition:all 0.15s ease;user-select:none;">' + t + '</span>'; });
html += '</div></div>';

// Upload date filter
html += '<div style="margin-bottom:18px;">';
html += '<div style="font-size:13px;font-weight:500;color:#606060;margin-bottom:8px;text-transform:uppercase;letter-spacing:0.5px;">Upload Date</div>';
html += '<div style="display:flex;flex-wrap:wrap;gap:6px;">';
var dates = ['Last hour', 'Today', 'This week', 'This month', 'This year'];
dates.forEach(function(d) { html += '<span class="filter-chip" data-filter="date" data-value="' + d + '" style="display:inline-block;padding:6px 14px;border-radius:16px;font-size:13px;cursor:pointer;background:#f2f2f2;color:#030303;border:1px solid #e5e5e5;transition:all 0.15s ease;user-select:none;">' + d + '</span>'; });
html += '</div></div>';

// Duration filter
html += '<div style="margin-bottom:18px;">';
html += '<div style="font-size:13px;font-weight:500;color:#606060;margin-bottom:8px;text-transform:uppercase;letter-spacing:0.5px;">Duration</div>';
html += '<div style="display:flex;flex-wrap:wrap;gap:6px;">';
var durations = ['Under 4 min', '4-20 min', 'Over 20 min'];
durations.forEach(function(d) { html += '<span class="filter-chip" data-filter="duration" data-value="' + d + '" style="display:inline-block;padding:6px 14px;border-radius:16px;font-size:13px;cursor:pointer;background:#f2f2f2;color:#030303;border:1px solid #e5e5e5;transition:all 0.15s ease;user-select:none;">' + d + '</span>'; });
html += '</div></div>';

// Sort by filter
html += '<div style="margin-bottom:18px;">';
html += '<div style="font-size:13px;font-weight:500;color:#606060;margin-bottom:8px;text-transform:uppercase;letter-spacing:0.5px;">Sort By</div>';
html += '<div style="display:flex;flex-wrap:wrap;gap:6px;">';
var sorts = ['Relevance', 'Upload date', 'View count', 'Rating'];
sorts.forEach(function(s) { html += '<span class="filter-chip" data-filter="sort" data-value="' + s + '" style="display:inline-block;padding:6px 14px;border-radius:16px;font-size:13px;cursor:pointer;background:#f2f2f2;color:#030303;border:1px solid #e5e5e5;transition:all 0.15s ease;user-select:none;">' + s + '</span>'; });
html += '</div></div>';

// Features filter
html += '<div style="margin-bottom:18px;">';
html += '<div style="font-size:13px;font-weight:500;color:#606060;margin-bottom:8px;text-transform:uppercase;letter-spacing:0.5px;">Features</div>';
html += '<div style="display:flex;flex-wrap:wrap;gap:6px;">';
var features = ['4K', 'HD', 'Subtitles/CC', 'Creative Commons', '360°', 'VR180', '3D', 'HDR'];
features.forEach(function(f) { html += '<span class="filter-chip" data-filter="feature" data-value="' + f + '" style="display:inline-block;padding:6px 14px;border-radius:16px;font-size:13px;cursor:pointer;background:#f2f2f2;color:#030303;border:1px solid #e5e5e5;transition:all 0.15s ease;user-select:none;">' + f + '</span>'; });
html += '</div></div>';

// Content filter
html += '<div style="margin-bottom:18px;">';
html += '<div style="font-size:13px;font-weight:500;color:#606060;margin-bottom:8px;text-transform:uppercase;letter-spacing:0.5px;">Content</div>';
html += '<div style="display:flex;flex-wrap:wrap;gap:6px;">';
var contents = ['Short', 'Long', 'Mix'];
contents.forEach(function(c) { html += '<span class="filter-chip" data-filter="content" data-value="' + c + '" style="display:inline-block;padding:6px 14px;border-radius:16px;font-size:13px;cursor:pointer;background:#f2f2f2;color:#030303;border:1px solid #e5e5e5;transition:all 0.15s ease;user-select:none;">' + c + '</span>'; });
html += '</div></div>';

// Active filters display
html += '<div id="active-filters-display" style="margin-top:20px;padding-top:16px;border-top:1px solid #e0e0e0;display:none;">';
html += '<div style="font-size:13px;font-weight:500;color:#606060;margin-bottom:8px;text-transform:uppercase;letter-spacing:0.5px;">Active Filters</div>';
html += '<div id="active-filters-list" style="display:flex;flex-wrap:wrap;gap:6px;"></div>';
html += '</div>';

sidebar.innerHTML = html;

// Add click handlers for chips
var chips = sidebar.querySelectorAll('.filter-chip');
chips.forEach(function(chip) {
  chip.addEventListener('click', function() {
    var isActive = this.classList.contains('active-filter-chip');

    // Toggle within same filter group
    var filterType = this.getAttribute('data-filter');
    var siblings = sidebar.querySelectorAll('[data-filter="' + filterType + '"]');

    if (!isActive) {
      siblings.forEach(function(sib) {
        sib.classList.remove('active-filter-chip');
        sib.style.background = '#f2f2f2';
        sib.style.color = '#030303';
        sib.style.borderColor = '#e5e5e5';
      });
      this.classList.add('active-filter-chip');
      this.style.background = '#e0e0e0';
      this.style.color = '#065fd4';
      this.style.borderColor = '#065fd4';
    } else {
      this.classList.remove('active-filter-chip');
      this.style.background = '#f2f2f2';
      this.style.color = '#030303';
      this.style.borderColor = '#e5e5e5';
    }

    // Update active filters display
    var activeChips = sidebar.querySelectorAll('.active-filter-chip');
    var activeDisplay = sidebar.querySelector('#active-filters-display');
    var activeList = sidebar.querySelector('#active-filters-list');

    if (activeChips.length > 0) {
      activeDisplay.style.display = 'block';
      activeList.innerHTML = '';
      activeChips.forEach(function(ac) {
        var badge = document.createElement('span');
        badge.style.cssText = 'display:inline-flex;align-items:center;gap:4px;padding:4px 10px;border-radius:12px;font-size:12px;background:#e8f0fe;color:#065fd4;';
        badge.textContent = ac.getAttribute('data-value');
        activeList.appendChild(badge);
      });
    } else {
      activeDisplay.style.display = 'none';
    }
  });
});

// Insert sidebar as first child
element.insertBefore(sidebar, element.firstChild);

if (element.dataset.widthAdjusted) return;
element.dataset.widthAdjusted = 'true';
element.style.marginLeft = '0';
element.style.flex = '1 1 auto';
element.style.minWidth = '0';

if (element.dataset.advancedChipsAdded) return;
element.dataset.advancedChipsAdded = 'true';

var advancedChips = [
  { label: '4K', icon: '🎬' },
  { label: 'HD', icon: '📺' },
  { label: 'Live', icon: '🔴' },
  { label: 'Shorts', icon: '⚡' },
  { label: 'Playlist', icon: '📋' },
  { label: 'Channel', icon: '👤' },
  { label: 'Movie', icon: '🎥' },
  { label: '4K', icon: '' },
  { label: 'HD', icon: '' },
  { label: 'Subtitles', icon: '💬' },
  { label: 'Creative Commons', icon: '🔄' },
  { label: 'Under 4 min', icon: '⏱️' },
  { label: 'Over 20 min', icon: '⏰' },
  { label: 'This week', icon: '📅' },
  { label: 'This month', icon: '🗓️' },
  { label: 'Most viewed', icon: '👁️' },
  { label: 'Newest', icon: '✨' }
];

// Only add unique chips not already present
var existingChips = element.querySelectorAll('yt-chip-cloud-chip-renderer');
var existingLabels = [];
existingChips.forEach(function(chip) {
  var textEl = chip.querySelector('#chip-shape-container div');
  if (textEl) {
    existingLabels.push(textEl.textContent.trim());
  }
});

advancedChips.forEach(function(chipData) {
  // Check if this label already exists
  var alreadyExists = false;
  existingLabels.forEach(function(existing) {
    if (existing.toLowerCase() === chipData.label.toLowerCase()) {
      alreadyExists = true;
    }
  });

  if (!alreadyExists) {
    var newChip = document.createElement('yt-chip-cloud-chip-renderer');
    newChip.setAttribute('chip-style', 'STYLE_HOME_FILTER');

    var chipShapeContainer = document.createElement('div');
    chipShapeContainer.id = 'chip-shape-container';
    chipShapeContainer.setAttribute('class', 'style-scope yt-chip-cloud-chip-renderer');

    var chipShape = document.createElement('chip-shape');
    chipShape.setAttribute('class', 'ytChipShapeHost style-scope yt-chip-cloud-chip-renderer');

    var button = document.createElement('button');
    button.setAttribute('class', 'ytChipShapeButtonReset style-scope chip-shape');
    button.setAttribute('role', 'tab');

    var chipDiv = document.createElement('div');
    chipDiv.setAttribute('class', 'ytChipShapeChip ytChipShapeInactive ytChipShapeOnlyTextPadding style-scope chip-shape');
    chipDiv.textContent = chipData.label;

    button.appendChild(chipDiv);
    chipShape.appendChild(button);
    chipShapeContainer.appendChild(chipShape);
    newChip.appendChild(chipShapeContainer);

    element.appendChild(newChip);
  }
});

if (element.dataset.layoutSet) return;
element.dataset.layoutSet = 'true';
element.style.display = 'flex';
element.style.flexDirection = 'row';
element.style.width = '100%';
